create or replace function public.can_write_luo_room(target_room uuid) returns boolean language sql stable security definer set search_path='' as $$
 select auth.uid() is not null and public.is_conversation_member(target_room) and exists(select 1 from public.conversations c where c.id=target_room and case when c.kind='direct' then not exists(select 1 from public.conversation_members cm join public.chat_user_blocks b on (b.blocker_id=auth.uid() and b.blocked_id=cm.user_id)or(b.blocker_id=cm.user_id and b.blocked_id=auth.uid()) where cm.conversation_id=c.id and cm.user_id<>auth.uid()) else not exists(select 1 from public.chat_group_rules where conversation_id=c.id and(archived or archive_at<=now())) and(coalesce((select member_text from public.chat_group_rules where conversation_id=c.id),true) or exists(select 1 from public.conversation_members where conversation_id=c.id and user_id=auth.uid() and role in('owner','admin'))) end);
$$;
alter table luo_internal.push_config add column last_wake timestamptz;
alter table luo_internal.push_queue alter column message_id drop not null,add column call_id uuid references public.chat_calls(id) on delete cascade,add constraint push_event_shape check(num_nonnulls(message_id,call_id)=1);
create unique index push_call_recipient_idx on luo_internal.push_queue(call_id,user_id,endpoint) where call_id is not null;
create function luo_internal.wake_push() returns trigger language plpgsql security definer set search_path='' as $$declare token text;begin
 update luo_internal.push_config set last_wake=clock_timestamp() where singleton and(last_wake is null or last_wake<clock_timestamp()-interval '5 seconds') returning worker_key into token;
 if token is not null then perform net.http_post(url:='https://byjixqwpjvsgmqilmzbm.supabase.co/functions/v1/luo-web-push',headers:=jsonb_build_object('Content-Type','application/json','Authorization','Bearer '||token),body:='{}',timeout_milliseconds:=10000);end if;return new;
 exception when others then return new;end;$$;
revoke all on function luo_internal.wake_push() from public,anon,authenticated;
create trigger wake_push_after_queue after insert on luo_internal.push_queue for each statement execute function luo_internal.wake_push();
create function luo_internal.enqueue_call_push() returns trigger language plpgsql security definer set search_path='' as $$begin
 insert into luo_internal.push_queue(call_id,user_id,endpoint) select new.id,s.user_id,s.endpoint from public.chat_push_subscriptions s where s.user_id=new.callee_id and luo_internal.push_allowed(s.user_id,new.conversation_id) on conflict do nothing;return new;exception when others then return new;end;$$;
revoke all on function luo_internal.enqueue_call_push() from public,anon,authenticated;
create trigger enqueue_luo_call_push after insert on public.chat_calls for each row execute function luo_internal.enqueue_call_push();
drop function public.claim_luo_push_work();
create function public.claim_luo_push_work() returns table(id bigint,user_id uuid,endpoint text,p256dh text,auth_key text,event_type text) language sql security definer set search_path='' as $$
 with chosen as(select q.id from luo_internal.push_queue q left join public.chat_messages m on m.id=q.message_id left join public.chat_calls c on c.id=q.call_id where q.available_at<=now() and(q.lease_until is null or q.lease_until<now()) and q.attempts<5 and q.created_at>now()-interval '1 day' and case when q.call_id is not null then c.status='ringing' and c.created_at>now()-interval '60 seconds' and luo_internal.push_allowed(q.user_id,c.conversation_id) and not exists(select 1 from public.chat_user_blocks where(blocker_id=q.user_id and blocked_id=c.caller_id)or(blocker_id=c.caller_id and blocked_id=q.user_id)) else m.id is not null and m.deleted_at is null and m.recalled_at is null and(m.expires_at is null or m.expires_at>now()) and luo_internal.push_allowed(q.user_id,m.conversation_id) and not exists(select 1 from public.chat_user_blocks where(blocker_id=q.user_id and blocked_id=m.sender_id)or(blocker_id=m.sender_id and blocked_id=q.user_id)) end order by(q.call_id is not null)desc,q.id for update of q skip locked limit 50),leased as(update luo_internal.push_queue q set attempts=q.attempts+1,lease_until=now()+interval '2 minutes',available_at=now()+interval '5 minutes' from chosen where q.id=chosen.id returning q.id,q.user_id,q.endpoint,q.call_id)select l.id,l.user_id,l.endpoint,s.p256dh,s.auth_key,case when l.call_id is not null then 'call' else 'message' end from leased l join public.chat_push_subscriptions s on s.user_id=l.user_id and s.endpoint=l.endpoint;$$;
revoke all on function public.claim_luo_push_work() from public,anon,authenticated;grant execute on function public.claim_luo_push_work() to service_role;
